select edu_student.* ,edu_trxorder_detail.course_score from edu_trxorder_detail left join edu_student on edu_trxorder_detail.user_id = edu_student.id left join edu_course on edu_trxorder_detail.course_id = edu_course.id where edu_course.is_deleted=0
and edu_trxorder_detail.course_id = #{student.courseId}
order by edu_trxorder_detail.create_time desc

select stus.* from (
select edu_student.*,(select MAX(edu_trxorder_detail.auth_time) from edu_trxorder_detail
where edu_trxorder_detail.course_id=#{student.courseId}
and edu_trxorder_detail.user_id=edu_student.id) as course_auth_time from edu_student

